import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BfWdyVj4.js";const h=JSON.parse('{"title":"Alarms and timers","description":"","frontmatter":{},"headers":[],"relativePath":"features/alarms.md","filePath":"features/alarms.md","lastUpdated":1793092343000}'),n={name:"features/alarms.md"};function r(d,e,i,l,c,m){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="alarms-and-timers" tabindex="-1">Alarms and timers <a class="header-anchor" href="#alarms-and-timers" aria-label="Permalink to &quot;Alarms and timers&quot;">​</a></h1><p>&quot;Wake me up at seven on school days&quot;, &quot;ten minutes for the cookies&quot;.</p><ul><li><code>set_alarm</code> sets an alarm at a time of day (24-hour <code>HH:MM</code>), with a label shown and read on the screen (&quot;School&quot;) and a repeat: <code>once</code>, <code>daily</code>, <code>weekdays</code> or <code>weekends</code>.</li><li><code>set_timer</code> starts a countdown, in minutes (fractions are fine; at most 12 hours).</li><li><code>list_alarms</code> and <code>cancel_alarm</code> manage them, and grown-ups can see and cancel them on the admin page.</li></ul><p>When one is due, the displays ring with <strong>Stop</strong> and <strong>Snooze</strong> (9 minutes) buttons. Alarms never ring quieter than 20%, whatever the display&#39;s volume. If a display was off when an alarm was due, it doesn&#39;t ring more than half an hour late.</p><p>They&#39;re kept on the server (<code>~/.config/froghub/alarms.json</code>), so they survive a display reloading, and run in the house&#39;s time zone. There can be at most 20.</p><p>Off with the grown-ups&#39; &quot;Set alarms and timers&quot; switch.</p>',6)])])}const p=a(n,[["render",r]]);export{h as __pageData,p as default};
